	credential, okCredential := lowerHex(credentialHex, 16)
	seed, okSeed := lowerHex(seedHex, 32)
	if !okCredential || !okSeed {
		return keyPairError("withruntime: the API key starts with rtsk_ but is not a key pair's secret (rtsk_<32 hex>_<64 hex>). Nothing was sent.")
	}
