	digest := sha256.Sum256(body)
	target := req.URL.RequestURI()
	m := make([]byte, 0, 92+len(req.Method)+len(target)+len(idempotencyKey)+2)
	m = append(m, "rtr\x01"...)
	m = append(m, idLE(credential)...)
	m = append(m, idLE(projectID)...)
	m = binary.LittleEndian.AppendUint64(m, at)
	m = append(m, nonce...)
	m = append(m, digest[:]...)
	m = append(m, req.Method+"\n"+target+"\n"+idempotencyKey...)
