			if !ok {
				continue
			}
			r := Route{Method: strings.ToUpper(method), Path: path, Params: []string{}, Query: []string{}, Body: "none"}
			params, _ := op["parameters"].([]any)
			for _, p := range params {
				pm, _ := p.(map[string]any)
				name, _ := pm["name"].(string)
				switch pm["in"] {
				case "path":
					r.Params = append(r.Params, name)
				case "query":
					r.Query = append(r.Query, name)
				}
			}
			rb, _ := op["requestBody"].(map[string]any)
			content, _ := rb["content"].(map[string]any)
			if _, ok := content["application/json"]; ok {
				r.Body = "json"
			} else if _, ok := content["application/octet-stream"]; ok {
				r.Body = "bytes"
			}
			responses, _ := op["responses"].(map[string]any)
			okr, _ := responses["200"].(map[string]any)
			okc, _ := okr["content"].(map[string]any)
			_, r.Raw = okc["application/octet-stream"]
			r.Idempotent = op["x-idempotent"] == true
